import sys
import os
import json
import csv
import datetime
from decimal import Decimal


def parse_date(val_str):
    s = val_str.strip()
    if not s:
        return None

    # Check for Excel serial number
    try:
        num = float(s)
        if 10000 <= num <= 100000:
            d = datetime.date(1899, 12, 30) + datetime.timedelta(days=int(round(num)))
            return d.strftime("%Y-%m-%d")
    except ValueError:
        pass

    # Try standard string date formats
    formats = [
        "%Y-%m-%d",
        "%m/%d/%Y",
        "%d/%m/%Y",
        "%Y/%m/%d",
        "%m-%d-%Y",
        "%B %d, %Y",
        "%b %d, %Y",
    ]
    for fmt in formats:
        try:
            dt = datetime.datetime.strptime(s, fmt).date()
            return dt.strftime("%Y-%m-%d")
        except ValueError:
            pass

    return s


def parse_amount(val_str):
    s = val_str.strip()
    if not s:
        return None
    cleaned = s.replace("$", "").replace(",", "")
    try:
        d = Decimal(cleaned)
        return cleaned, d
    except Exception:
        return None


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    # Load all CSV files in the packet directory
    docs_data = {}  # doc_name -> {entity_id: [row_dict, ...]}
    doc_field_map = {}  # doc_name -> {normalized_field_name: actual_field_name}

    for fname in os.listdir(packet_dir):
        if fname.lower().endswith(".csv"):
            doc_name = os.path.splitext(fname)[0]
            fpath = os.path.join(packet_dir, fname)
            rows_by_entity = {}
            with open(fpath, "r", encoding="utf-8-sig", newline="") as csvfile:
                reader = csv.DictReader(csvfile)
                if reader.fieldnames:
                    norm_fields = {k.strip().upper(): k for k in reader.fieldnames if k}
                    doc_field_map[doc_name] = norm_fields

                    # Determine entity key column
                    id_col = None
                    for candidate in ["CASE_NUMBER", "CASE_NO", "ID"]:
                        if candidate in norm_fields:
                            id_col = norm_fields[candidate]
                            break
                    if not id_col and reader.fieldnames:
                        id_col = reader.fieldnames[0]

                    for row in reader:
                        entity_id = row.get(id_col, "").strip()
                        if entity_id:
                            rows_by_entity.setdefault(entity_id, []).append(row)

            docs_data[doc_name] = rows_by_entity

    # Mapping of (rule_id, fact_name) -> (doc_name, col_name, type)
    fact_rules = {
        ("lca.wage_105", "offered wage"): ("lca_disclosure", "WAGE_RATE_OF_PAY_FROM", "amount"),
        ("lca.wage_105", "prevailing wage"): ("lca_disclosure", "PREVAILING_WAGE", "amount"),
        ("lca.three_years", "begin date"): ("lca_disclosure", "BEGIN_DATE", "date"),
        ("lca.three_years", "end date"): ("lca_disclosure", "END_DATE", "date"),
    }

    # Fallback generic fact mapping
    generic_fact_rules = {
        "offered wage": ("lca_disclosure", "WAGE_RATE_OF_PAY_FROM", "amount"),
        "prevailing wage": ("lca_disclosure", "PREVAILING_WAGE", "amount"),
        "begin date": ("lca_disclosure", "BEGIN_DATE", "date"),
        "end date": ("lca_disclosure", "END_DATE", "date"),
    }

    pairs = manifest.get("pairs", [])
    facts_spec = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        rule_id, entity_id = pair.split("::", 1)
        fact_names = facts_spec.get(rule_id, [])

        pair_result = {}
        for fact_name in fact_names:
            mapping = fact_rules.get((rule_id, fact_name)) or generic_fact_rules.get(fact_name)
            if not mapping:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name, col_name, val_type = mapping
            doc_rows = docs_data.get(doc_name, {})
            entity_rows = doc_rows.get(entity_id, [])

            if not entity_rows:
                pair_result[fact_name] = "ABSENT"
                continue

            # Resolve actual column name
            actual_col = col_name
            if doc_name in doc_field_map:
                actual_col = doc_field_map[doc_name].get(col_name.upper(), col_name)

            extracted_values = []
            for row in entity_rows:
                raw_val = row.get(actual_col, "")
                if raw_val is None:
                    continue
                raw_val = raw_val.strip()
                if not raw_val:
                    continue

                if val_type == "date":
                    parsed = parse_date(raw_val)
                    if parsed is not None:
                        extracted_values.append((parsed, parsed))
                elif val_type == "amount":
                    parsed = parse_amount(raw_val)
                    if parsed is not None:
                        str_val, dec_val = parsed
                        extracted_values.append((str_val, dec_val))
                else:
                    extracted_values.append((raw_val, raw_val))

            if not extracted_values:
                pair_result[fact_name] = "ABSENT"
            else:
                # Check for conflict
                first_compare = extracted_values[0][1]
                has_conflict = False
                for _, cmp_val in extracted_values[1:]:
                    if cmp_val != first_compare:
                        has_conflict = True
                        break

                if has_conflict:
                    pair_result[fact_name] = "CONFLICT"
                else:
                    repr_val = extracted_values[0][0]
                    pair_result[fact_name] = [repr_val, doc_name]

        output[pair] = pair_result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()
