import csv
from datetime import date, datetime, timedelta
from decimal import Decimal
import json
import os
import sys

FACT_TO_COL = {
    "offered wage": "WAGE_RATE_OF_PAY_FROM",
    "prevailing wage": "PREVAILING_WAGE",
    "begin date": "BEGIN_DATE",
    "end date": "END_DATE",
}


def parse_date(val):
    if not val:
        return None
    val = val.strip()
    if not val:
        return None
    try:
        num = float(val)
        if 1000 < num < 100000:
            d = date(1899, 12, 30) + timedelta(days=int(round(num)))
            return d.strftime("%Y-%m-%d")
    except ValueError:
        pass

    for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y/%m/%d", "%d-%m-%Y"):
        try:
            return datetime.strptime(val, fmt).strftime("%Y-%m-%d")
        except ValueError:
            pass
    return val


def parse_amount(val):
    if not val:
        return None
    val = val.strip().replace("$", "").replace(",", "")
    if not val:
        return None
    try:
        d = Decimal(val)
        return str(d)
    except Exception:
        return val


def normalize_value(val, fact_name, col_name):
    if val is None:
        return None
    val = str(val).strip()
    if not val:
        return None

    fact_lower = fact_name.lower()
    col_upper = col_name.upper()

    if "date" in fact_lower or col_upper in ("BEGIN_DATE", "END_DATE"):
        return parse_date(val)
    elif "wage" in fact_lower or col_upper in (
        "WAGE_RATE_OF_PAY_FROM",
        "WAGE_RATE_OF_PAY_TO",
        "PREVAILING_WAGE",
    ):
        return parse_amount(val)
    else:
        return val


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    # Locate lca_disclosure file
    disclosure_file = None
    doc_name = "lca_disclosure"
    for fname in os.listdir(packet_dir):
        base, ext = os.path.splitext(fname)
        if base.lower() == "lca_disclosure" and ext.lower() == ".csv":
            disclosure_file = os.path.join(packet_dir, fname)
            doc_name = base
            break

    # Read records from CSV
    records_by_case = {}
    if disclosure_file and os.path.exists(disclosure_file):
        with open(disclosure_file, "r", encoding="utf-8-sig", newline="") as f:
            reader = csv.DictReader(f)
            for row in reader:
                case_no = (
                    row.get("CASE_NUMBER") or row.get("case_number") or ""
                ).strip()
                if case_no:
                    records_by_case.setdefault(case_no, []).append(row)

    facts_by_rule = manifest.get("facts", {})
    pairs = manifest.get("pairs", [])

    output = {}

    for pair in pairs:
        if "::" in pair:
            rule_id, entity_id = pair.split("::", 1)
        else:
            rule_id, entity_id = pair, ""

        facts = facts_by_rule.get(rule_id, [])
        entity_rows = records_by_case.get(entity_id, [])

        pair_result = {}

        for fact in facts:
            fact_lower = fact.lower().strip()
            col_name = FACT_TO_COL.get(fact_lower)

            if not col_name:
                # Fallback to column matching
                for target_col in [
                    "JOB_TITLE",
                    "SOC_CODE",
                    "SOC_TITLE",
                    "FULL_TIME_POSITION",
                    "BEGIN_DATE",
                    "END_DATE",
                    "WAGE_RATE_OF_PAY_FROM",
                    "WAGE_RATE_OF_PAY_TO",
                    "PREVAILING_WAGE",
                    "PW_WAGE_LEVEL",
                    "WORKSITE_CITY",
                    "WORKSITE_STATE",
                ]:
                    if target_col.replace("_", " ").lower() == fact_lower:
                        col_name = target_col
                        break

            if not col_name:
                pair_result[fact] = "ABSENT"
                continue

            values = set()
            for row in entity_rows:
                raw_val = row.get(col_name)
                norm_val = normalize_value(raw_val, fact, col_name)
                if norm_val is not None:
                    values.add(norm_val)

            if len(values) == 0:
                pair_result[fact] = "ABSENT"
            elif len(values) == 1:
                pair_result[fact] = [next(iter(values)), doc_name]
            else:
                pair_result[fact] = "CONFLICT"

        output[pair] = pair_result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()
