import sys
import os
import json
import csv
import datetime

def parse_date(val):
    if val is None:
        return None
    val = str(val).strip()
    if not val:
        return None

    # Check if numeric (e.g. Excel serial date)
    try:
        num = float(val)
        if 1000 <= num <= 100000:
            d = datetime.date(1899, 12, 30) + datetime.timedelta(days=int(num))
            return d.strftime("%Y-%m-%d")
    except ValueError:
        pass

    # Try parsing standard date strings
    for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%m/%d/%y", "%Y/%m/%d", "%d-%m-%Y", "%d/%m/%Y", "%B %d, %Y", "%b %d, %Y"):
        try:
            d = datetime.datetime.strptime(val, fmt).date()
            return d.strftime("%Y-%m-%d")
        except ValueError:
            pass

    return val

def format_amount(val):
    if val is None:
        return None
    val = str(val).strip().replace('$', '').replace(',', '')
    if not val:
        return None
    try:
        f = float(val)
        if f.is_integer():
            return str(int(f))
        else:
            return str(f)
    except ValueError:
        return val

def format_string(val):
    if val is None:
        return None
    val = str(val).strip()
    return val if val else None

# Mapping from fact name to (document_name, column_name, type)
FACT_MAPPING = {
    "offered wage": ("lca_disclosure", "WAGE_RATE_OF_PAY_FROM", "amount"),
    "prevailing wage": ("lca_disclosure", "PREVAILING_WAGE", "amount"),
    "begin date": ("lca_disclosure", "BEGIN_DATE", "date"),
    "end date": ("lca_disclosure", "END_DATE", "date"),
    "job title": ("lca_disclosure", "JOB_TITLE", "string"),
    "soc code": ("lca_disclosure", "SOC_CODE", "string"),
    "soc title": ("lca_disclosure", "SOC_TITLE", "string"),
    "full time position": ("lca_disclosure", "FULL_TIME_POSITION", "string"),
    "wage level": ("lca_disclosure", "PW_WAGE_LEVEL", "string"),
    "pw wage level": ("lca_disclosure", "PW_WAGE_LEVEL", "string"),
    "prevailing wage level": ("lca_disclosure", "PW_WAGE_LEVEL", "string"),
    "worksite city": ("lca_disclosure", "WORKSITE_CITY", "string"),
    "worksite state": ("lca_disclosure", "WORKSITE_STATE", "string"),
    "offered wage to": ("lca_disclosure", "WAGE_RATE_OF_PAY_TO", "amount"),
}

def load_lca_disclosure(file_path):
    records_by_case = {}
    with open(file_path, "r", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)
        for row in reader:
            normalized_row = {k.strip().upper(): v.strip() for k, v in row.items() if k is not None}
            case_num = normalized_row.get("CASE_NUMBER")
            if case_num:
                records_by_case.setdefault(case_num, []).append(normalized_row)
    return records_by_case

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    # Locate documents in packet directory
    doc_files = {}
    for root, _, files in os.walk(packet_dir):
        for f in files:
            base, _ = os.path.splitext(f)
            doc_files[base] = os.path.join(root, f)

    # Cache loaded records by document name
    loaded_docs = {}
    if "lca_disclosure" in doc_files:
        loaded_docs["lca_disclosure"] = load_lca_disclosure(doc_files["lca_disclosure"])
    else:
        loaded_docs["lca_disclosure"] = {}

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" in pair:
            rule_id, entity = pair.split("::", 1)
        else:
            continue

        pair_facts = facts_by_rule.get(rule_id, [])
        pair_output = {}

        for fact in pair_facts:
            mapping = FACT_MAPPING.get(fact.strip().lower())
            if not mapping:
                pair_output[fact] = "ABSENT"
                continue

            doc_name, col_name, val_type = mapping
            doc_records = loaded_docs.get(doc_name, {})
            entity_records = doc_records.get(entity, [])

            if not entity_records:
                pair_output[fact] = "ABSENT"
                continue

            extracted_values = set()
            for record in entity_records:
                raw_val = record.get(col_name)
                if not raw_val:
                    continue

                if val_type == "date":
                    formatted = parse_date(raw_val)
                elif val_type == "amount":
                    formatted = format_amount(raw_val)
                else:
                    formatted = format_string(raw_val)

                if formatted is not None:
                    extracted_values.add(formatted)

            if len(extracted_values) == 0:
                pair_output[fact] = "ABSENT"
            elif len(extracted_values) == 1:
                val = next(iter(extracted_values))
                pair_output[fact] = [val, doc_name]
            else:
                pair_output[fact] = "CONFLICT"

        output[pair] = pair_output

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
